CREATE TABLE counterparty_accounts(counterparty_id INTEGER PRIMARY KEY REFERENCES counterparties(id),company_id INTEGER NOT NULL REFERENCES companies(id),purchases_account TEXT NOT NULL DEFAULT '',expenses_account TEXT NOT NULL DEFAULT '',preferred_group TEXT CHECK(preferred_group IN ('2','6')),approved_by TEXT NOT NULL,approved_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,version INTEGER NOT NULL DEFAULT 1,CHECK(purchases_account='' OR substr(purchases_account,1,1)='2'),CHECK(expenses_account='' OR substr(expenses_account,1,1)='6'));
CREATE TRIGGER counterparty_accounts_scope BEFORE INSERT ON counterparty_accounts WHEN NOT EXISTS(SELECT 1 FROM counterparties WHERE id=NEW.counterparty_id AND company_id=NEW.company_id) BEGIN SELECT RAISE(ABORT,'counterparty company mismatch'); END;
INSERT INTO counterparty_accounts(counterparty_id,company_id,purchases_account,expenses_account,preferred_group,approved_by) SELECT counterparty_id,company_id,CASE WHEN substr(account,1,1)='2' THEN account ELSE '' END,CASE WHEN substr(account,1,1)='6' THEN account ELSE '' END,substr(account,1,1),approved_by FROM account_mappings WHERE substr(account,1,1) IN ('2','6');
